INSERT [dbo].[USCB Course Catalog - 11.4.26] ([Academic_Year_Description], [Academic_Term], [Course_Campus], [Course_Campus_Description], [College], [College_Description], [Dept], [Department_Description], [Course_Levels], [Course_Identification], [Subject], [Subject_Description], [Course_Number], [Status], [Status_Description], [Title_Short_Description], [Title_Long_Description], [Schedule_Type], [Instructional_Method], [CIP_Code], [Program_Classification], [Minimum_Credit], [Maximum_Credit], [Minimum_Contact], [Course_Description], [Default_Grade_Mode], [Default_Grade_Mode_Description], [Grade_Modes], [Prereq_Check_Method_Description], [Equivalent_Courses], [Course_Department_Restrictions]) VALUES (N'2026-2027', N'Fall 2026', N'BFT', N'Beaufort', N'2A', N'Univ of S Carolina Beaufort', N'2EDU', N'USC-B Education', N'UG', N'EDECB435', N'EDEC', N'EDEC - Early Childhood Educ', N'B435', N'A', N'Active', N'Math Experiences in ECE', N'Math Experiences in Early Childhood Education', N'Lecture', NULL, 131210, N'Early Childhood Educ &Teaching', 3, NULL, 3, N'(Prerequisite: EDCI B100; Admission to the Professional Program in Education or consent of the Department Chair; Co-requisites: EDEC B436, EDEC B444, EDEC B440P). This methods course includes the basic content of the academic area of mathematics to be presented to PreK-3rd grade children. Developmentally appropriate experiences, learning activities, materials and equipment to aid in the development of math concepts in young children are presented. Diversity-related influences and needs of exceptional learners are also addressed.', N'S', N'Standard Letter', N'S - Standard Letter', N'CAPP', N'BEDE435', NULL)
