INSERT [dbo].[USCB Course Catalog - 11.4.26] ([Academic_Year_Description], [Academic_Term], [Course_Campus], [Course_Campus_Description], [College], [College_Description], [Dept], [Department_Description], [Course_Levels], [Course_Identification], [Subject], [Subject_Description], [Course_Number], [Status], [Status_Description], [Title_Short_Description], [Title_Long_Description], [Schedule_Type], [Instructional_Method], [CIP_Code], [Program_Classification], [Minimum_Credit], [Maximum_Credit], [Minimum_Contact], [Course_Description], [Default_Grade_Mode], [Default_Grade_Mode_Description], [Grade_Modes], [Prereq_Check_Method_Description], [Equivalent_Courses], [Course_Department_Restrictions]) VALUES (N'2026-2027', N'Fall 2026', N'BFT', N'Beaufort', N'2A', N'Univ of S Carolina Beaufort', N'2NUR', N'USC-B Nursing', N'UG', N'NURSB312', N'NURS', N'NURS - Nursing', N'B312', N'A', N'Active', N'Assessment & Physical Exam', N'Assessment and Physical Examination of Individuals', N'Lab / Clinical', NULL, 513801, N'Registered Nursing', 3, NULL, 5, N'(Prerequisite: Acceptance to the Pre-licensure program, RN licensure or consent of instructor) Students will conduct a systematic patient examination
to determine the health, health risk, and health alterations from disease conditions. The focus is on adults with normal physiologic variation and extends to include age, gender, and socio-cultural variants. Using assessment findings students will derive clinical problem statements, determine risk reduction strategies, and align assessment findings with laboratory and other diagnostic results to create a comprehensive health profile.', N'S', N'Standard Letter', N'E - Exam/Exemption Credit; F - Academic & Grade Forgiveness; S - Standard Letter', N'Banner Basic', N'BNUR312; NURSA307', NULL)
GO
