INSERT [dbo].[USCB Course Catalog - 11.4.26] ([Academic_Year_Description], [Academic_Term], [Course_Campus], [Course_Campus_Description], [College], [College_Description], [Dept], [Department_Description], [Course_Levels], [Course_Identification], [Subject], [Subject_Description], [Course_Number], [Status], [Status_Description], [Title_Short_Description], [Title_Long_Description], [Schedule_Type], [Instructional_Method], [CIP_Code], [Program_Classification], [Minimum_Credit], [Maximum_Credit], [Minimum_Contact], [Course_Description], [Default_Grade_Mode], [Default_Grade_Mode_Description], [Grade_Modes], [Prereq_Check_Method_Description], [Equivalent_Courses], [Course_Department_Restrictions]) VALUES (N'2026-2027', N'Fall 2026', N'BFT', N'Beaufort', N'2A', N'Univ of S Carolina Beaufort', N'2NUR', N'USC-B Nursing', N'UG', N'NURSB415', N'NURS', N'NURS - Nursing', N'B415', N'I', N'Inactive', N'Gerontological Rehab Nursing', N'Gerontological and Rehabilitation Nursing', N'Lecture', NULL, 513801, N'Registered Nursing', 3, NULL, 3, N'(Prerequisite: NURS B301 or NURS B326 and NURSB 312; Pre or Co-requisite: NURS B350)  Care and special needs of the older adult in various care settings. Gerontological nursing, presentation of disease, rehabilitation, health promotion, reimbursement and a comprehensive nursing gerontological assessment are covered. (Lecture 3 hours).', N'S', N'Standard Letter', N'S - Standard Letter', N'CAPP', N'BNUR415; NURSA417', NULL)
