INSERT [dbo].[USCB Course Catalog - 11.4.26] ([Academic_Year_Description], [Academic_Term], [Course_Campus], [Course_Campus_Description], [College], [College_Description], [Dept], [Department_Description], [Course_Levels], [Course_Identification], [Subject], [Subject_Description], [Course_Number], [Status], [Status_Description], [Title_Short_Description], [Title_Long_Description], [Schedule_Type], [Instructional_Method], [CIP_Code], [Program_Classification], [Minimum_Credit], [Maximum_Credit], [Minimum_Contact], [Course_Description], [Default_Grade_Mode], [Default_Grade_Mode_Description], [Grade_Modes], [Prereq_Check_Method_Description], [Equivalent_Courses], [Course_Department_Restrictions]) VALUES (N'2026-2027', N'Fall 2026', N'BFT', N'Beaufort', N'2A', N'Univ of S Carolina Beaufort', N'2HSS', N'USC-B Humanities & Social Sci', N'UG', N'PHILB315', N'PHIL', N'PHIL - Philosophy', N'B315', N'A', N'Active', N'Philosophy of Technology', N'Philosophy of Technology', N'USCB Final Exam', NULL, 380101, N'Philosophy.', 3, NULL, 3, N'This course will focus on the various philosophical questions and issues that arise from the technological opportunities and challenges of the 21st century. Philosophical topics surrounding technology will include those related to ethics, the philosophy of language, feminism, critical theory, and pragmatism. Possible topics regarding technology may include information technologies, robotics, AI, genetic engineering, cyborgs, climate change/geoengineering/the Anthropocene, and social media technologies. Finally, we investigate how technological developments stimulate philosophical thinking.
', N'S', N'Standard Letter', N'A - Audit; S - Standard Letter', N'Banner Basic', NULL, NULL)
GO
